THEMES_NE.update({
5: [
 ("कुन श्रेष्ठ?", "अर्जुन सोध्छन् — कर्मसंन्यास कि कर्मयोग, कुन श्रेष्ठ; कृष्ण भन्नुहुन्छ दुवैले कल्याण दिन्छन्, तर कर्मयोग विशिष्ट छ।",
  [("अर्जुनको प्रश्न", "तपाईं कर्मको संन्यास प्रशंसा गर्नुहुन्छ, र योग पनि; दुईमध्ये कुन श्रेयस्कर हो निश्चित भन्नुहोस्।", "5.01", "5.01"),
   ("दुवैले कल्याण दिन्छन् — तर योग विशिष्ट", "संन्यास र कर्मयोग दुवैले परम कल्याण दिन्छन्; तर दुईमध्ये कर्मसंन्यासभन्दा कर्मयोग विशिष्ट छ।", "5.02", "5.02")]),
 ("साङ्ख्य र योग एउटै हुन्", "बालबुद्धिहरूले मात्र दुई मार्गलाई फरक भन्छन्; एउटैमा राम्ररी स्थित हुनेले दुवैको फल पाउँछ।",
  [("नित्य संन्यासी", "जसले न घृणा गर्छ न आकाङ्क्षा — त्यसलाई नित्य संन्यासी जान; द्वन्द्वरहित भई ऊ सजिलै बन्धनबाट मुक्त हुन्छ।", "5.03", "5.03"),
   ("बालकहरूले मात्र फरक भन्छन्", "साङ्ख्य र योग फरक हुन् भन्छन् बालकहरूले, पण्डितले होइन; एउटैमा राम्ररी स्थित हुनेले दुवैको फल पाउँछ। साङ्ख्यहरूले पाउने स्थान योगीहरूले पनि पाउँछन् — जसले दुवैलाई एक देख्छ, उसैले देख्छ।", "5.04", "5.05"),
   ("योगबिना संन्यास कठिन", "तर योगबिना संन्यास पाउन कठिन छ; योगयुक्त मुनि चाँडै ब्रह्म पाउँछ।", "5.06", "5.06")]),
 ("कर्म गर्दा पनि लिप्त हुँदैन", "शुद्धात्मा कर्मयोगीले 'म केही गर्दिनँ' जान्दछ, र पाप उसमा टाँसिँदैन — कमलपातमा पानी नटाँसिएझैँ।",
  [("सबै प्राणीको आत्मा", "योगयुक्त, विशुद्धात्मा, विजितात्मा, जितेन्द्रिय, सबै प्राणीको आत्मा भएको — कर्म गर्दा पनि लिप्त हुँदैन।", "5.07", "5.07"),
   ("‘म केही गर्दिनँ’", "'म केही गर्दिनँ' — तत्त्ववित्ले यसै ठान्छ: हेर्दा, सुन्दा, छुँदा, सुँघ्दा, खाँदा, हिँड्दा, सुत्दा, सास फेर्दा, बोल्दा, त्याग्दा, समात्दा, आँखा खोल्दा-चिम्लँदा — इन्द्रियहरू विषयमा वर्तिन्छन् भन्ने जानेर।", "5.08", "5.09"),
   ("कमलको पात", "ब्रह्ममा कर्म अर्पण गरी आसक्ति त्यागी कर्म गर्नेलाई पाप छुँदैन, कमलको पातलाई पानीले नछोएझैँ।", "5.10", "5.10"),
   ("आत्मशुद्धिका लागि कर्म", "योगीहरू शरीर, मन, बुद्धि वा इन्द्रियमात्रले आसक्ति त्यागी आत्मशुद्धिका लागि कर्म गर्छन्।", "5.11", "5.11"),
   ("फल त्यागेर शान्ति", "युक्त पुरुषले कर्मफल त्यागी नैष्ठिकी शान्ति पाउँछ; अयुक्तले कामले प्रेरित भई फलमा आसक्त हुँदै बाँधिन्छ।", "5.12", "5.12")]),
 ("नौ ढोकाको नगर", "मनले सबै कर्म त्यागेर देही नौ ढोकाको नगरमा सुखपूर्वक बस्छ — न कर्म गर्दै, न गराउँदै।",
  [("नौ ढोकाको नगर", "मनले सबै कर्म त्यागेर देही नौ ढोकाको नगरमा सुखपूर्वक बस्छ — न कर्म गर्दै, न गराउँदै।", "5.13", "5.13"),
   ("प्रभुले कर्तृत्व सिर्जना गर्नुहुन्न", "प्रभुले लोकका लागि न कर्तृत्व, न कर्म, न कर्मफलको संयोग सिर्जना गर्नुहुन्छ — स्वभावले नै प्रवर्तन हुन्छ।", "5.14", "5.14"),
   ("न पाप लिनुहुन्छ", "विभुले कसैको पाप वा पुण्य लिनुहुन्न; अज्ञानले ज्ञान ढाकिएको छ, त्यसैले प्राणीहरू मोहित हुन्छन्।", "5.15", "5.15"),
   ("ज्ञानले सूर्यझैँ प्रकाश दिन्छ", "तर जसको अज्ञान आत्मज्ञानले नष्ट भएको छ, त्यो ज्ञानले सूर्यझैँ परम तत्त्व प्रकाशित गर्छ।", "5.16", "5.16")]),
 ("समदर्शन", "बुद्धि, मन र श्रद्धा त्यसैमा राखेको ज्ञानीले ब्राह्मण, गाई, हात्ती, कुकुर र चाण्डालमा समान देख्छ।",
  [("त्यसैमा तल्लीन", "बुद्धि त्यसैमा, आत्मा त्यसैमा, निष्ठा त्यसैमा, परायण त्यही — ज्ञानले पाप नष्ट भई तिनीहरू नफर्किने गति पाउँछन्।", "5.17", "5.17"),
   ("ज्ञानीले सबैमा समान देख्छ", "विद्या-विनययुक्त ब्राह्मण, गाई, हात्ती, कुकुर र चाण्डालमा पण्डितहरू समान देख्छन्। जसको मन समतामा स्थित छ, उसले यहीँ संसार जित्यो; ब्रह्म निर्दोष र सम छ, त्यसैले तिनीहरू ब्रह्ममै स्थित छन्।", "5.18", "5.19"),
   ("न हर्ष, न उद्वेग", "प्रिय पाएर नहर्षाउने, अप्रिय पाएर नउद्विग्न हुने, स्थिरबुद्धि र असम्मूढ ब्रह्मवित् ब्रह्ममै स्थित हुन्छ।", "5.20", "5.20"),
   ("भित्रको आनन्द", "बाह्य स्पर्शमा अनासक्त भई आत्मामा भएको सुख पाउँछ; ब्रह्मयोगमा युक्त भई अक्षय सुख भोग्छ।", "5.21", "5.21")]),
 ("भोग दुःखका योनि हुन्", "संयोगबाट जन्मेका भोग आदि-अन्त भएका र दुःखका योनि हुन्; बुद्धिमान् तिनमा रमाउँदैन।",
  [("संयोगजन्य भोग दुःखका योनि", "संयोगबाट जन्मेका भोग दुःखका योनि हुन्, आदि र अन्त भएका; बुद्धिमान् तिनमा रमाउँदैन।", "5.22", "5.22"),
   ("काम र क्रोध सहन सक्ने", "शरीर छुट्नुअघि यहीँ काम र क्रोधको वेग सहन सक्ने — त्यो युक्त हो, त्यो सुखी हो।", "5.23", "5.23"),
   ("जसको आनन्द भित्रै छ", "जसको सुख भित्र, आराम भित्र, ज्योति पनि भित्रै छ — त्यो योगी ब्रह्म भई ब्रह्मनिर्वाण पाउँछ।", "5.24", "5.24"),
   ("ब्रह्मनिर्वाण", "पाप नष्ट भएका, संशय काटिएका, संयतात्मा, सबै प्राणीको हितमा रमाउने ऋषिहरूले ब्रह्मनिर्वाण पाउँछन्। काम र क्रोधबाट मुक्त, संयतचित्त, आत्मज्ञानीहरूका लागि ब्रह्मनिर्वाण नजिकै छ।", "5.25", "5.26")]),
 ("योगीको ध्यान", "बाह्य स्पर्श बाहिरै राखी, दृष्टि भ्रूमध्यमा, प्राण-अपान सम — मलाई सबै प्राणीको सुहृद् जान्ने शान्ति पाउँछ।",
  [("प्राण, दृष्टि र स्थिरता", "बाह्य स्पर्श बाहिरै राखी, दृष्टि भ्रूमध्यमा राखी, नासिकाभित्र चल्ने प्राण र अपान सम गरी — इन्द्रिय, मन र बुद्धि संयत, मोक्षपरायण, इच्छा-भय-क्रोधरहित मुनि सदा मुक्त छ।", "5.27", "5.28"),
   ("मलाई सबैको सुहृद् जानेर शान्ति पाउँछ", "मलाई यज्ञ र तपको भोक्ता, सबै लोकको महेश्वर, सबै प्राणीको सुहृद् जानेर शान्ति पाउँछ।", "5.29", "5.29")]),
],
})

THEMES_NE.update({
6: [
 ("साँचो संन्यासी", "संन्यास भनेको अग्नि र कर्म त्याग्नु होइन, फलको आश्रय त्याग्नु हो; सङ्कल्प नत्यागी कोही योगी हुँदैन।",
  [("अग्नि नबाल्ने होइन", "फलको आश्रय नलिई कर्तव्य कर्म गर्ने नै संन्यासी र योगी हो — अग्नि नबाल्ने र क्रिया नगर्ने होइन।", "6.01", "6.01"),
   ("संन्यास नै योग हो", "जसलाई संन्यास भनिन्छ त्यही योग हो जान; सङ्कल्प नत्यागेको कोही योगी हुँदैन।", "6.02", "6.02"),
   ("आरोहीलाई कर्म, आरूढलाई शम", "योगमा आरोहण गर्न चाहने मुनिका लागि कर्म साधन हो; आरूढ भइसकेकाका लागि शम साधन हो।", "6.03", "6.03"),
   ("जब कतै आसक्त हुँदैन", "जब न इन्द्रियविषयमा न कर्ममा आसक्त हुन्छ, सबै सङ्कल्प त्यागेको हुन्छ — तब ऊ योगारूढ भनिन्छ।", "6.04", "6.04")]),
 ("आफैँले आफूलाई उठाऊ", "आत्मा नै आत्माको मित्र हो र शत्रु पनि; जितिएको आत्माका लागि मित्र, नजितिएकाका लागि शत्रुझैँ।",
  [("आत्मा नै मित्र, आत्मा नै शत्रु", "आफैँले आफूलाई उठाओस्, आफूलाई नगिराओस्; आत्मा नै आत्माको मित्र हो, र आत्मा नै आत्माको शत्रु। जसले आत्माद्वारा आत्मा जितेको छ, उसका लागि आत्मा मित्र हो — तर नजित्नेका लागि आत्मा शत्रुझैँ शत्रुतामा रहन्छ।", "6.05", "6.06"),
   ("जितात्मा शान्त हुन्छ", "जितात्मा र प्रशान्त पुरुषको परमात्मा समाहित हुन्छ — शीत-उष्ण, सुख-दुःख, मान-अपमानमा समान।", "6.07", "6.07"),
   ("ढिक्को, ढुङ्गा र सुन समान", "ज्ञान-विज्ञानले तृप्त, कूटस्थ, जितेन्द्रिय योगी युक्त भनिन्छ — जसलाई ढिक्को, ढुङ्गा र सुन समान छन्।", "6.08", "6.08"),
   ("मित्र र शत्रुमा समान", "सुहृद्, मित्र, शत्रु, उदासीन, द्वेष्य, बन्धु, साधु र पापी — सबैमा समबुद्धि हुने विशिष्ट छ।", "6.09", "6.09")]),
 ("ध्यानको आसन", "व्यावहारिक निर्देश: एकान्त स्थान, न अग्लो न होचो दृढ आसन, शरीर सिधा र निश्चल।",
  [("एकान्तमा, एक्लै", "योगीले एकान्तमा बसी, एक्लै, चित्त र शरीर संयत गरी, निराशी र अपरिग्रही भई निरन्तर आत्मामा युक्त होस्।", "6.10", "6.10"),
   ("शुद्ध ठाउँ, न अग्लो न होचो", "शुद्ध ठाउँमा, न अति अग्लो न अति होचो, कुश-मृगछाला-वस्त्र क्रमशः ओछ्याएर दृढ आसन बनाई — त्यहाँ बसेर मन एकाग्र गरी, चित्त र इन्द्रियको क्रिया संयत गरी आत्मशुद्धिका लागि योग अभ्यास गरोस्।", "6.11", "6.12"),
   ("शरीर, टाउको र घाँटी सिधा", "शरीर, टाउको र घाँटी सिधा र निश्चल राखी, आफ्नै नाकको टुप्पोमा दृष्टि राखी, अन्तै नहेरी — प्रशान्त, निर्भय, ब्रह्मचर्यव्रतमा स्थित, मन संयत गरी ममा चित्त राखी बसोस्।", "6.13", "6.14"),
   ("निर्वाणमा पर्यवसित शान्ति", "यसरी सधैँ आत्मा युक्त गर्दै संयतमन योगीले ममा रहेको, निर्वाणमा पर्यवसित परम शान्ति पाउँछ।", "6.15", "6.15")]),
 ("कुनै कुरा अति होइन", "अति खाने वा नखाने, अति सुत्ने वा नसुत्नेका लागि योग होइन — यो मध्यमार्ग हो।",
  [("अति खानेका लागि होइन", "अति खानेका लागि योग होइन, नखानेका लागि पनि होइन; अति सुत्ने र सधैँ जाग्नेका लागि पनि होइन।", "6.16", "6.16"),
   ("आहार, निद्रा र कर्ममा मित", "मित आहार-विहार, कर्ममा मित चेष्टा, निद्रा र जागरणमा मित हुनेका लागि योग दुःखनाशक हुन्छ।", "6.17", "6.17")]),
 ("वायुरहित ठाउँको दियो", "संयत चित्त आत्मामै स्थिर हुँदा त्यो वायुरहित ठाउँको दियोझैँ हुन्छ, जुन कँपिँदैन।",
  [("जब मन आत्मामा स्थिर हुन्छ", "संयत चित्त आत्मामै स्थिर हुँदा, सबै कामनाबाट निःस्पृह भएपछि — तब ऊ युक्त भनिन्छ।", "6.18", "6.18"),
   ("वायुरहित ठाउँको दियोझैँ", "वायुरहित ठाउँको दियो कँपिँदैन — योगीको संयत चित्तको त्यही उपमा दिइन्छ, आत्मयोगको अभ्यास गर्दै।", "6.19", "6.19"),
   ("आत्मामै सन्तुष्ट", "जहाँ योगाभ्यासले निरुद्ध चित्त शान्त हुन्छ, र आत्माद्वारा आत्मा देखेर आत्मामै सन्तुष्ट हुन्छ — त्यो अत्यन्त सुख, इन्द्रियातीत बुद्धिले ग्रहण गरिने, जसमा स्थित भई तत्त्वबाट कहिल्यै चल्दैन —", "6.20", "6.21"),
   ("यसभन्दा ठूलो लाभ छैन", "— जुन पाएपछि अरू कुनै लाभ ठूलो ठान्दैन, र जसमा स्थित भई ठूलो दुःखले पनि विचलित हुँदैन।", "6.22", "6.22"),
   ("अनिर्विण्ण चित्तले अभ्यास गर", "दुःखसंयोगबाट वियोग नै योग हो जान; त्यो योग निश्चयपूर्वक, अनिर्विण्ण चित्तले अभ्यास गर्नुपर्छ।", "6.23", "6.23")]),
 ("मनलाई फर्काएर ल्याऊ", "सङ्कल्पबाट जन्मेका सबै कामना त्याग; अनि शनैः शनैः बुद्धिले मनलाई शान्त पार — र जता भाग्छ, त्यतैबाट फर्काऊ।",
  [("सङ्कल्पजन्य कामना त्याग", "सङ्कल्पबाट जन्मेका सबै कामना निःशेष त्यागी, मनले नै इन्द्रियसमूहलाई सबैतिरबाट संयत गरी —", "6.24", "6.24"),
   ("शनैः शनैः शान्त होस्", "— धैर्ययुक्त बुद्धिले बिस्तारै-बिस्तारै शान्त होस्; मन आत्मामा राखी अरू केही नसोचोस्।", "6.25", "6.25"),
   ("जता मन भाग्छ, त्यतैबाट फर्काऊ", "चञ्चल र अस्थिर मन जुन-जुन कारणले भाग्छ, त्यहीँबाट रोकेर आत्माको वशमा ल्याओस्।", "6.26", "6.26")]),
 ("सबैमा आत्मा देख्नु", "प्रशान्त, निष्पाप योगीलाई परम सुख आउँछ; उसले सबै प्राणीमा आत्मा र आत्मामा सबै प्राणी देख्छ — र म उसका लागि कहिल्यै हराउँदिनँ।",
  [("निष्पापलाई परम सुख", "प्रशान्तमन, शान्तरज, ब्रह्मभूत, निष्पाप योगीलाई परम सुख आउँछ। यसरी निरन्तर आत्मा युक्त गर्दै, निष्पाप योगीले ब्रह्मसंस्पर्शको अत्यन्त सुख सजिलै पाउँछ।", "6.27", "6.28"),
   ("सबैमा आत्मा — म कहिल्यै हराउँदिनँ", "सबै प्राणीमा आत्मा र आत्मामा सबै प्राणी देख्दै ऊ सर्वत्र समान देख्छ। जसले मलाई सबैतिर देख्छ र सबै ममा देख्छ — उसका लागि म हराउँदिनँ, ऊ मेरा लागि हराउँदैन।", "6.29", "6.30"),
   ("परम योगी", "एकत्वमा स्थित भई सबै प्राणीमा रहेको मलाई भज्ने योगी जुनसुकै अवस्थामा रहे पनि ममै रहन्छ। जसले आफ्नै उपमाले सर्वत्र समान देख्छ — सुख वा दुःखमा — त्यो परम योगी मानिन्छ।", "6.31", "6.32")]),
 ("चञ्चल मन", "अर्जुन भन्छन् मन वायुझैँ थाम्न कठिन छ; कृष्ण अभ्यास र वैराग्यले उत्तर दिनुहुन्छ।",
  [("अर्जुन: यो योग असम्भव लाग्छ", "तपाईंले भन्नुभएको समत्वरूपी योगको स्थिर स्थिति चञ्चलताका कारण म देख्दिनँ।", "6.33", "6.33"),
   ("मन वायुझैँ चञ्चल छ", "मन चञ्चल, प्रमाथी, बलवान् र दृढ छ; त्यसलाई थाम्नु वायु थाम्नुजस्तै कठिन लाग्छ।", "6.34", "6.34"),
   ("अभ्यास र वैराग्यले", "निस्सन्देह मन चञ्चल र थाम्न कठिन छ — तर अभ्यास र वैराग्यले त्यसलाई थाम्न सकिन्छ।", "6.35", "6.35"),
   ("असंयतका लागि योग कठिन", "असंयत आत्मा भएकाका लागि योग पाउन कठिन छ; तर संयतात्माले उपायपूर्वक प्रयत्न गरे पाउन सकिन्छ।", "6.36", "6.36")]),
 ("योगबाट चुक्ने योगी", "प्रयत्न गरेर पनि नपुग्नेको के हुन्छ? ऊ नष्ट हुँदैन — शुभ कर्म गर्ने कहिल्यै दुर्गतिमा जाँदैन।",
  [("नपुग्नेको के हुन्छ?", "श्रद्धा भए पनि प्रयत्नहीन, मन योगबाट चुकेको, सिद्धि नपाएको — कुन गति पाउँछ? दुवैबाट भ्रष्ट, आश्रयहीन भई ब्रह्मपथमा छिन्न बादलझैँ नष्ट हुँदैन र?", "6.37", "6.38"),
   ("शुभ कर्म गर्ने दुर्गतिमा जाँदैन", "मेरो यो संशय पूर्णतः तपाईंले मात्र हटाउन सक्नुहुन्छ; तपाईंबाहेक अरू कोही छैन। न यस लोकमा न परलोकमा उसको विनाश छ; शुभ कर्म गर्ने कोही दुर्गतिमा जाँदैन।", "6.39", "6.40"),
   ("शुद्ध घरमा जन्मन्छ", "पुण्यवान्का लोक पाएर धेरै वर्ष बसेपछि योगभ्रष्ट शुचि र श्रीमान्को घरमा जन्मन्छ।", "6.41", "6.41"),
   ("वा योगीहरूको कुलमा", "अथवा ज्ञानी योगीहरूकै कुलमा जन्मन्छ — यस्तो जन्म संसारमा अत्यन्त दुर्लभ छ।", "6.42", "6.42"),
   ("पूर्वजन्मको बुद्धि फेरि पाउँछ", "त्यहाँ पूर्वदेहको बुद्धिसंयोग फेरि पाउँछ, र सिद्धिका लागि पुनः प्रयत्न गर्छ।", "6.43", "6.43")]),
 ("श्रेष्ठ योगी", "पूर्वाभ्यासले नै ऊ अघि बढ्छ; धेरै जन्ममा शुद्ध भई परम गति पाउँछ — र सबैमा श्रेष्ठ मलाई भज्ने हो।",
  [("पूर्वाभ्यासले अघि बढ्छ", "त्यही पूर्वाभ्यासले नै ऊ अवश हुँदै पनि अघि बढ्छ; योगको जिज्ञासु पनि शब्दब्रह्मलाई नाघ्छ।", "6.44", "6.44"),
   ("धेरै जन्ममा सिद्ध", "प्रयत्नपूर्वक अभ्यास गर्ने, पापबाट शुद्ध भएको, धेरै जन्ममा सिद्ध भएको योगीले परम गति पाउँछ।", "6.45", "6.45"),
   ("योगी तपस्वीभन्दा श्रेष्ठ", "योगी तपस्वीभन्दा श्रेष्ठ छ, ज्ञानीभन्दा पनि श्रेष्ठ मानिन्छ, कर्मीभन्दा पनि श्रेष्ठ — त्यसैले योगी होऊ, हे अर्जुन।", "6.46", "6.46"),
   ("सबैमा प्रिय: मलाई भज्ने", "सबै योगीहरूमध्ये पनि जसले श्रद्धावान् भई अन्तरात्मा ममा राखी मलाई भज्छ — त्यो मेरा लागि सबैभन्दा युक्ततम हो।", "6.47", "6.47")]),
],
})

