 ("शिक्षा कसलाई दिने", "यो शिक्षा तपस्वीहीन, श्रद्धारहित वा कपटीलाई होइन; तर जसले भक्तिसाथ मेरा भक्तहरूलाई यो सिकाउँछ, र जसले श्रद्धाले यो सुन्छ — दुवै मुक्त हुन्छन्।",
  [("अयोग्यलाई होइन", "यो कुरा न तपस्या बिनाकोलाई भन्नुपर्छ, न श्रद्धारहितलाई, न सेवा नगर्नेलाई, न मलाई निन्दा गर्नेलाई।", "18.67", "18.67"),
   ("सिकाउनेको फल", "जसले मेरा भक्तहरूलाई भक्तिसाथ यो परम गोप्य सिकाउँछ — मलाई आफ्नो उच्चतम प्रेम दिएर — ऊ मकहाँ आउनेछ।", "18.68", "18.69"),
   ("सुन्नेको फल", "उसभन्दा बढी मेरो सेवा गर्ने कोही छैन; र जसले यो पवित्र संवाद श्रद्धाले, निन्दा बिना सुन्छ — मुक्त भएर — शुभ लोकहरूमा पुग्छ।", "18.70", "18.71")]),
 ("निष्कर्ष", "कृष्ण सोध्छन् के अर्जुनले सुने; अर्जुनले आफ्नो मोह नष्ट भएको घोषणा गर्छन्; सञ्जयले संवादको प्रशंसा गर्छन्, र अन्तिम श्लोकले जहाँ कृष्ण र अर्जुन छन्, त्यहाँ विजय हुन्छ भन्छ।",
  [("भगवान्को प्रश्न", "हे पार्थ, के यो तिमीले एकाग्र मनले सुन्यौ? के अज्ञानको मोह नष्ट भयो?", "18.72", "18.72"),
   ("अर्जुनको घोषणा", "मेरो मोह नष्ट भयो; हे अच्युत, तपाईंको कृपाले मैले स्मृति पाएँ; म स्थिर छु, मेरो सन्देह गयो — म तपाईंको आज्ञा पालन गर्नेछु।", "18.73", "18.73"),
   ("सञ्जयको गवाही", "यसरी मैले वासुदेव र महात्मा पार्थको अद्भुत, रोमाञ्चक संवाद सुनेँ।", "18.74", "18.74"),
   ("व्यासको कृपा", "व्यासको कृपाले मैले यो परम गोप्य योग — योगेश्वर कृष्ण आफैं बोलेको — सुनेँ।", "18.75", "18.75"),
   ("स्मरणको आनन्द", "केशव र अर्जुनको यो अद्भुत संवाद बारम्बार सम्झेर, म बारम्बार रमाउँछु।", "18.76", "18.77"),
   ("अन्तिम विजय", "जहाँ योगेश्वर कृष्ण र धनुर्धारी पार्थ छन् — त्यहाँ समृद्धि, विजय, वैभव र निश्चित नीति छन्; यो मेरो विश्वास हो।", "18.78", "18.78")]),
